-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.search_user_messages(p_query text)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select c.id
  from public.conversations c
  left join public.profiles p
    on p.id = case when c.participant_a = auth.uid() then c.participant_b else c.participant_a end
  where (c.participant_a = auth.uid() or c.participant_b = auth.uid())
    and (
      c.last_message_preview ilike '%' || p_query || '%'
      or p.display_name ilike '%' || p_query || '%'
      or p.username ilike '%' || p_query || '%'
      or exists (
        select 1 from public.messages m
        where m.conversation_id = c.id
          and m.body ilike '%' || p_query || '%'
      )
    )
  order by c.last_message_at desc nulls last
  limit 50;
$function$;

grant execute on function public.search_user_messages(p_query text) to anon;
grant execute on function public.search_user_messages(p_query text) to authenticated;
grant execute on function public.search_user_messages(p_query text) to public;
grant execute on function public.search_user_messages(p_query text) to service_role;
